#define LED 13      // Определение пина, к которому подключен светодиод

void setup() {
  pinMode(LED, OUTPUT);  // Настройка пина LED как выхода
}

void loop() {
  digitalWrite(LED, HIGH);  // Включаем светодиод
  delay(1000);              // Пауза 1 секунда

  digitalWrite(LED, LOW);   // Выключаем светодиод
  delay(1000);              // Пауза 1 секунда
}
